begin;
select no_plan();
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
insert into cooksmith.planned_meals(id,household_id,title,meal_date,meal_type) values('10200000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Synthetic dinner','2026-10-09','dinner');
insert into cooksmith.household_pantry_items(id,household_id,name,category,quantity,unit,available) values('10200000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001','Synthetic rice','other',1000,'g',true);
create temporary table completion_request as select p.updated_at plan_version,jsonb_build_array(jsonb_build_object('pantryItemId',s.id,'name',s.name,'unit',s.unit,'amount',600,'updatedAt',s.updated_at)) lines from cooksmith.planned_meals p cross join cooksmith.household_pantry_items s where p.id='10200000-0000-4000-8000-000000000001' and s.id='10200000-0000-4000-8000-000000000002';
select throws_ok($$update cooksmith.planned_meals set completed_at=now() where id='10200000-0000-4000-8000-000000000001'$$,'42501',null,'Cannot forge completion independently of stock receipt');
select lives_ok($$select cooksmith.meal_stock_command('20000000-0000-4000-8000-000000000001','10200000-0000-4000-8000-000000000003','10200000-0000-4000-8000-000000000001','done',0,(select plan_version from completion_request),(select lines from completion_request))$$,'Done atomically records measured usage');
select is((select quantity from cooksmith.household_pantry_items where id='10200000-0000-4000-8000-000000000002'),400::numeric,'600g used from 1000g');
select ok((select completed_at is not null from cooksmith.planned_meals where id='10200000-0000-4000-8000-000000000001'),'Completion persisted');
select lives_ok($$select cooksmith.meal_stock_command('20000000-0000-4000-8000-000000000001','10200000-0000-4000-8000-000000000003','10200000-0000-4000-8000-000000000001','done',0,(select plan_version from completion_request),(select lines from completion_request))$$,'Response-loss exact retry returns original receipt');
select is((select quantity from cooksmith.household_pantry_items where id='10200000-0000-4000-8000-000000000002'),400::numeric,'Retry cannot deduct again');
select throws_ok($$select cooksmith.meal_stock_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'10200000-0000-4000-8000-000000000001','done',0,(select plan_version from completion_request),'[]')$$,'PT409',null,'New operation with stale completion generation rejected');
select throws_ok($$update cooksmith.planned_meals set title='Changed source' where id='10200000-0000-4000-8000-000000000001'$$,'PT409',null,'Source edit requires undo');
select lives_ok($$update cooksmith.planned_meals set meal_date='2026-10-10' where id='10200000-0000-4000-8000-000000000001'$$,'Move leaves usage untouched');
update cooksmith.household_pantry_items set quantity=650 where id='10200000-0000-4000-8000-000000000002';
update completion_request set plan_version=(select updated_at from cooksmith.planned_meals where id='10200000-0000-4000-8000-000000000001'),lines=cooksmith.meal_stock_undo_review('20000000-0000-4000-8000-000000000001','10200000-0000-4000-8000-000000000001',1)->'lines';
select lives_ok($$select cooksmith.meal_stock_command('20000000-0000-4000-8000-000000000001','10200000-0000-4000-8000-000000000004','10200000-0000-4000-8000-000000000001','undo',1,(select plan_version from completion_request),(select lines from completion_request))$$,'Reviewed undo uses recorded delta after later stock change');
select is((select quantity from cooksmith.household_pantry_items where id='10200000-0000-4000-8000-000000000002'),1250::numeric,'Undo adds recorded 600g, never replaces later balance');
select is((select completion_revision from cooksmith.planned_meals where id='10200000-0000-4000-8000-000000000001'),2,'Completion generation advances through undo');
select throws_ok($$delete from cooksmith.meal_stock_operations$$,'42501',null,'Audit receipts cannot be erased by clients');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select is((select count(*) from cooksmith.meal_stock_operations),0::bigint,'Unrelated household cannot read receipt history');
select throws_ok($$select cooksmith.meal_stock_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'10200000-0000-4000-8000-000000000001','done',2,now(),'[]')$$,'42501',null,'Forged household denied');
select throws_ok($$select cooksmith.meal_stock_command('20000000-0000-4000-8000-000000000002',gen_random_uuid(),'10200000-0000-4000-8000-000000000001','done',2,now(),'[]')$$,'42501',null,'Foreign plan identifier denied in own household');
reset role;
select ok(not has_function_privilege('anon','cooksmith.meal_stock_command(uuid,uuid,uuid,text,integer,timestamptz,jsonb)','execute'),'Anonymous command denied');
select * from finish();
rollback;
